/**
* Convierte un DID completo, method-specific-id o fragmento a bytes32 (hex string 0x...).
* Maneja correctamente el formato estándar `did:isbe:<modelId>:<hex>`.
*/
export declare function didToBytes32(did: string): string;
/**
* Convierte un vMethodId (did#fragment) a bytes32 (para contrato)
*/
export declare function vMethodIdToBytes32(vMethodId: string): string;
